<?php
declare(strict_types=1);
function mh_action(int $id,string $action,array $d):array{
 $stored=null;$storageLock=null;try{return crm_idempotent('manual:result:'.$id.':'.$action,$d,function()use($id,$action,$d,&$stored,&$storageLock){$base=mh_result($id);$j=mh_job((int)$base['job_id'],true);$s=mh_current($j);$r=crm_query('SELECT * FROM nd_manual_results WHERE id=? FOR UPDATE',[$id])->fetch();
 if((int)crm_query('SELECT MAX(id) FROM nd_manual_results WHERE job_id=?',[$j['id']])->fetchColumn()!==$id)crm_fail(409,'Эта редакция уже заменена.');if(!is_string($d['checksum']??null)||!hash_equals($r['checksum'],$d['checksum'])||!hash_equals($r['checksum'],hash('sha256',$r['body'])))crm_fail(409,'Контрольная сумма результата изменилась.');
 if($action==='deliver'&&$r['state']==='DELIVERED')return ['ok'=>true,'id'=>$id,'revision_id'=>(int)$r['delivery_revision_id']];crm_version($d,$r);$body=json_decode($r['body'],true);$report=mh_checks($body);
 if($action==='check'){
  if($r['state']!=='DRAFT')crm_fail(409,'Проверить можно только текущий черновик.');$state=match($report['verdict']){'PASS'=>'READY','FAIL'=>'QA_REJECTED',default=>'BLOCKED'};crm_query('UPDATE nd_manual_results SET review_json=?,state=?,version=version+1 WHERE id=?',[ai_json($report),$state,$id]);
 }elseif($action==='changes'){
  if(!in_array($r['state'],['DRAFT','READY','QA_REJECTED','BLOCKED','APPROVED'],true))crm_fail(409,'Эту редакцию нельзя отправить на доработку.');$feedback=cc_text($d,'feedback',1000);crm_query("UPDATE nd_manual_results SET state='CHANGES_REQUESTED',feedback=?,version=version+1 WHERE id=?",[$feedback,$id]);
 }elseif($action==='approve'){
  if($r['state']!=='READY'||$report['verdict']!=='PASS'||($d['confirm']??false)!==true)crm_fail(409,'Нужны доступные проверки и точное подтверждение владельца.');crm_query("UPDATE nd_manual_results SET state='APPROVED',approved_by=1,approved_checksum=checksum,approved_at=UTC_TIMESTAMP(),version=version+1 WHERE id=?",[$id]);
 }elseif($action==='deliver'){
  if($r['state']!=='APPROVED'||$report['verdict']!=='PASS'||!is_string($r['approved_checksum'])||!hash_equals($r['checksum'],$r['approved_checksum'])||($d['confirm']??false)!==true)crm_fail(409,'Передача требует отдельного одобрения точной редакции.');
  $bytes=ai_json(['format'=>'neurodelo-manual-delivery-v1','files'=>$body['files'],'qa'=>$report,'limitations'=>['Ручная передача. Код не исполнялся. Статическая проверка не доказывает работоспособность приложения.'],'source'=>['job_id'=>(int)$j['id'],'result_id'=>$id,'revision'=>(int)$r['revision_number'],'checksum'=>$r['checksum']]]);$fid=prod_generated_json((int)$j['project_id'],$bytes,$stored,$storageLock);crm_query('UPDATE nd_manual_results SET file_id=? WHERE id=?',[$fid,$id]);crm_query("UPDATE nd_cc_files SET visibility='customer',version=version+1 WHERE id=?",[$fid]);$a=['type'=>'owner','id'=>1];
  $doc=cc_create_document_effect($a,(int)$j['project_id'],['kind'=>'deliverable','title'=>'Результат ручного задания №'.$j['id'],'fields'=>['title'=>'Результат ручного задания №'.$j['id'],'description'=>'Пакет JSON с документами, инструкциями и ограничениями.','acceptance'=>implode("\n",$s['criteria']),'comments'=>'Ручная передача. Проверены только перечисленные статические критерии.'],'file_ids'=>[$fid]]);$ready=cc_ready_effect($a,(int)$doc['id'],['version'=>(int)$doc['revision']['version']]);cc_submit_effect($a,(int)$doc['id'],['version'=>(int)$ready['revision']['version'],'confirm'=>true]);crm_query("UPDATE nd_manual_results SET state='DELIVERED',delivery_revision_id=?,version=version+1 WHERE id=?",[$doc['id'],$id]);
 }else crm_fail(404,'Действие не найдено.');cc_event(['type'=>'owner','id'=>1],(int)$j['project_id'],'manual_'.$action);return ['ok'=>true,'id'=>$id];});}catch(Throwable $e){if($stored)cc_cleanup_upload($stored);throw $e;}finally{if(is_resource($storageLock)){flock($storageLock,LOCK_UN);fclose($storageLock);}}
}
